    here = os.path.dirname(os.path.abspath(__file__))
    os.makedirs(os.path.join(here, "specs"), exist_ok=True)
    meta = []
    for v in V:
        name = f"{v['nr']:02d}_{v['slug']}"
        if not v.get("spec_vorhanden"):
            json.dump({"titel": v["titel"], "thumb": v["thumb"], "folien": v["folien"]},
                      open(os.path.join(here, "specs", name + ".json"), "w", encoding="utf-8"), ensure_ascii=False, indent=1)
        assert len(v["titel"]) <= 100, v["titel"]
        meta.append({k: v[k] for k in ("nr", "slug", "pl", "termin", "titel", "lead", "tags")} | {"name": name})
    json.dump(meta, open(os.path.join(here, "meta.json"), "w", encoding="utf-8"), ensure_ascii=False, indent=1)
    print(len(meta), "Videos")
